def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Opening: cooperate to build trust
    if n < 4:
        return 'C'

    # Fast feature extraction over recent window
    w = 12 if n >= 12 else n
    recent = history[-w:]
    recent_op_d = 0
    recent_my_d = 0
    for a, b in recent:
        if b == 'D':
            recent_op_d += 1
        if a == 'D':
            recent_my_d += 1

    # Total opponent cooperation count
    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Opponent's trailing defection streak and cooperation streak
    def_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            def_streak += 1
        else:
            break
    coop_streak = 0
    for a, b in reversed(history):
        if b == 'C':
            coop_streak += 1
        else:
            break

    last_my, last_op = history[-1]
    rounds_left = 100 - n

    # --- Endgame: last 2 rounds, defect if opponent has been forgiving ---
    if rounds_left <= 1:
        return 'D'
    if rounds_left <= 3:
        if opp_d == 0:
            return 'D'
        if last_op == 'C' and coop_streak >= 2:
            return 'D'
        if opp_d * 3 <= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # --- Opponent is almost always defecting: defect hard ---
    if opp_d >= 8 and opp_d * 3 >= n * 2:
        # rare forgiveness probe to escape mutual DD
        if def_streak >= 8 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- Opponent heavily cooperative: harvest cooperatively, probe sparingly ---
    if opp_d <= 1:
        # Extremely reliable cooperator: exploit in late-mid game
        if n >= 70 and rng.random() < 0.35:
            return 'D'
        if n >= 40 and coop_streak >= 20 and rng.random() < 0.10:
            return 'D'
        return 'C'

    # --- Opponent clearly cooperative overall ---
    if opp_d * 4 <= n:
        # Defect occasionally to probe
        if last_op == 'C':
            if coop_streak >= 12 and rng.random() < 0.14:
                return 'D'
            return 'C'
        # last_op == 'D'
        if def_streak >= 3:
            return 'D'
        # forgive single defection often
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    # --- Opponent often defecting ---
    if opp_d * 2 >= n:
        if def_streak >= 2:
            # mutual defection spiral: occasionally try to restart
            if rng.random() < 0.06:
                return 'C'
            return 'D'
        if last_op == 'D':
            # punish but sometimes attempt reset
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # opponent cooperated but is generally aggressive
        if recent_op_d >= 3:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        if rng.random() < 0.10:
            return 'D'
        return 'C'

    # --- Mixed opponent: robust tit-for-tat with measured forgiveness ---
    if last_op == 'D':
        if def_streak >= 4:
            return 'D'
        if recent_op_d >= 5:
            return 'D'
        # respond but sometimes forgive to look for cooperation
        if rng.random() < 0.40:
            return 'C'
        return 'D'

    # last_op == 'C'
    if recent_op_d >= 4 and coop_streak <= 1:
        # opponent just returned to C after many defects; be cautious
        if rng.random() < 0.20:
            return 'D'
        return 'C'
    # sustained cooperation: probe rarely
    if coop_streak >= 15 and rng.random() < 0.07:
        return 'D'
    if last_my == 'D' and coop_streak >= 1:
        return 'C'
    return 'C'
